Date: Sat, 21 Nov 2026 14:23:31 +0100
Subject: [PATCH] libdbusmenuqt: show a submenu once its items arrive

Submenu items are only fetched when the submenu is about to show, and
QMenu won't show an empty menu, so the first hover showed nothing. Show
the submenu once its items arrive if its entry is still hovered.

BUG: 442877
---
 libdbusmenuqt/dbusmenuimporter.cpp | 11 +++++++++++
 1 file changed, 11 insertions(+)

diff --git a/libdbusmenuqt/dbusmenuimporter.cpp b/libdbusmenuqt/dbusmenuimporter.cpp
index 7e821921de..d81c1c5346 100644
--- a/libdbusmenuqt/dbusmenuimporter.cpp
+++ b/libdbusmenuqt/dbusmenuimporter.cpp
@@ -447,6 +447,17 @@ void DBusMenuImporter::slotGetLayoutFinished(QDBusPendingCallWatcher *watcher)
         }
     }

+    // QMenu doesn't show a submenu that is still empty when it's hovered, so show it now if its entry is still active
+    auto *parentMenu = qobject_cast<QMenu *>(menu->parentWidget());
+    if (parentMenu && parentMenu->isVisible() && parentMenu->activeAction() == menu->menuAction() && !menu->isVisible()) {
+        const auto actions = menu->actions();
+        if (std::any_of(actions.cbegin(), actions.cend(), [](QAction *action) {
+                return action->isVisible();
+            })) {
+            parentMenu->setActiveAction(menu->menuAction());
+        }
+    }
+
     Q_EMIT menuUpdated(menu);
 }

